;(()=>{const STYLE_ID="yph-duration-badge-setting-style";function apply(v){document.body?.classList.toggle("yph-hide-duration-badges",!v)}async function read(){try{const s=await window.getSettings();return s.showDurationBadges!==false}catch{return true}}async function save(v){try{await window.storeObject("showDurationBadges",!!v)}catch(e){console.warn("[YPH] Failed to save showDurationBadges",e)}apply(v);window.logSystemEvent&&await window.logSystemEvent("INFO",`[SETTINGS] Saved setting: showDurationBadges`);window.success&&window.success("Setting saved");window.dispatchEvent(new Event("settings-changed"))}function installStyle(){if(document.getElementById(STYLE_ID))return;const s=document.createElement("style");s.id=STYLE_ID;s.textContent="body.yph-hide-duration-badges .duration-badge{display:none!important}";document.head?.appendChild(s)}async function addSettingsRow(){if(location.hash!=="#/settings"||document.querySelector("[data-yph-duration-setting]"))return;const rows=[...document.querySelectorAll(".toggle-row")];const anchor=rows.find(r=>r.textContent?.includes("Auto-save changes"));if(!anchor)return;const row=document.createElement("div");row.className=anchor.className;row.dataset.yphDurationSetting="1";const info=document.createElement("div");info.className="toggle-info svelte-1xc311x";const title=document.createElement("span");title.textContent="Pokazuj plakietki z czasem";title.className="svelte-1xc311x";const sub=document.createElement("span");sub.className="sub-text svelte-1xc311x";sub.textContent="Pokazuj lub ukrywaj plakietki z czasem trwania na miniaturkach";info.append(title,sub);const toggle=document.createElement("div");toggle.className="toggle-container svelte-1ryl1ss";toggle.setAttribute("role","switch");toggle.tabIndex=0;const cb=document.createElement("input");cb.type="checkbox";cb.style.display="none";cb.setAttribute("aria-label","Pokazuj plakietki z czasem");const track=document.createElement("div");track.className="toggle-track svelte-1ryl1ss";const thumb=document.createElement("div");thumb.className="toggle-thumb svelte-1ryl1ss";track.appendChild(thumb);toggle.append(cb,track);async function set(v){cb.checked=v;toggle.setAttribute("aria-checked",String(v));track.classList.toggle("checked",v);thumb.classList.toggle("checked",v);await save(v)}const initial=await read();cb.checked=initial;toggle.setAttribute("aria-checked",String(initial));track.classList.toggle("checked",initial);thumb.classList.toggle("checked",initial);toggle.addEventListener("click",()=>set(!cb.checked));toggle.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();set(!cb.checked)}});row.append(info,toggle);anchor.after(row)}async function init(){installStyle();apply(await read());if(location.hash==="#/settings")await addSettingsRow()}init();new MutationObserver(()=>{installStyle();if(location.hash==="#/settings")addSettingsRow()}).observe(document.documentElement,{childList:true,subtree:true});window.addEventListener("hashchange",()=>setTimeout(()=>addSettingsRow(),50));window.addEventListener("settings-changed",()=>read().then(apply))})();


;(()=>{
  const NAV_STYLE_ID="yph-saved-playlists-nav-style";
  const ORDER_KEY="managePlaylistOrder";
  let timer=0, observer=null, lastSignature="";

  function installNavStyle(){
    if(document.getElementById(NAV_STYLE_ID)) return;
    const st=document.createElement("style");
    st.id=NAV_STYLE_ID;
    st.textContent=`.sidenav.svelte-181dlmc{overflow-y:auto;overflow-x:hidden;scrollbar-gutter:stable}`;
    document.head.appendChild(st);
  }

  async function getOrder(){
    try{
      const value=await window.fetchObject?.(ORDER_KEY,[]);
      return Array.isArray(value)?value:[];
    }catch{return[]}
  }

  function getActivePlaylistId(){
    try{
      const hash=location.hash||"";
      const search=location.search||"";
      if(hash.startsWith("#/editor")||hash.startsWith("#/playlist")){
        const hashQuery=hash.includes("?")?hash.slice(hash.indexOf("?")+1):"";
        const hashId=new URLSearchParams(hashQuery).get("id");
        if(hashId)return decodeURIComponent(hashId);
        const searchId=new URLSearchParams(search).get("id");
        return searchId?decodeURIComponent(searchId):null;
      }
    }catch{}
    return null;
  }

  function updateActiveState(){
    const activeId=getActivePlaylistId();
    document.querySelectorAll('[data-yph-saved-playlists] a[data-playlist-id]').forEach(a=>{
      a.classList.toggle('active',!!activeId&&a.dataset.playlistId===activeId);
    });
  }

  const CACHE_KEY="yph:savedNavCache";
  let cached=null;
  try{const raw=localStorage.getItem(CACHE_KEY);const v=raw&&JSON.parse(raw);if(Array.isArray(v?.list))cached=v.list.filter(p=>p&&p.id)}catch{}

  function getGroups(){
    return [...document.querySelectorAll('.desktop-sidenav .top-nav .nav-group, .mobile-drawer .nav-group')];
  }

  function groupHasNav(group,withBox){
    if(!group.querySelector('[data-yph-saved-playlists-separator]'))return false;
    return !withBox||!!group.querySelector('[data-yph-saved-playlists]');
  }

  // Synchronous DOM build (no awaits) so it can run inside a MutationObserver
  // callback, i.e. before the browser paints and the list never visibly disappears.
  function buildNav(groups,playlists){
    if(observer)observer.disconnect();
    try{
      const activeId=getActivePlaylistId();
      for(const group of groups){
        group.querySelector('[data-yph-saved-playlists]')?.remove();
        group.querySelector('[data-yph-saved-playlists-separator]')?.remove();
        const manage=[...group.querySelectorAll('a')].find(a=>(a.getAttribute('href')||'')==='#/manage');
        const all=[...group.querySelectorAll('a')].find(a=>(a.getAttribute('href')||'')==='#/saved');
        if(!manage)continue;
        const sep=document.createElement('hr');
        sep.className='nav-divider svelte-181dlmc';
        sep.dataset.yphSavedPlaylistsSeparator='1';
        manage.after(sep);
        if(!playlists.length)continue;
        const box=document.createElement('div');
        box.className='yph-saved-playlists-nav svelte-181dlmc';
        box.dataset.yphSavedPlaylists='1';
        for(const playlist of playlists){
          const a=document.createElement('a');
          a.href=`#/playlist?id=${encodeURIComponent(playlist.id)}`;
          a.className='svelte-181dlmc';
          a.title=playlist.title||'Bez tytułu';
          a.dataset.playlistId=playlist.id;
          if(activeId===playlist.id)a.classList.add('active');
          const icon=document.createElement('span');
          icon.className='yph-playlist-icon svelte-181dlmc';
          if(all?.firstElementChild){const ic=all.firstElementChild.cloneNode(true);const svg=ic.tagName&&ic.tagName.toLowerCase()==='svg'?ic:ic.querySelector?.('svg');if(svg){svg.setAttribute('viewBox','0 0 512 512');const pth=svg.querySelector('path');if(pth)pth.setAttribute('d','M64 144a48 48 0 1 0 0-96 48 48 0 1 0 0 96zM192 64c-17.7 0-32 14.3-32 32s14.3 32 32 32l288 0c17.7 0 32-14.3 32-32s-14.3-32-32-32L192 64zm0 160c-17.7 0-32 14.3-32 32s14.3 32 32 32l288 0c17.7 0 32-14.3 32-32s-14.3-32-32-32l-288 0zm0 160c-17.7 0-32 14.3-32 32s14.3 32 32 32l288 0c17.7 0 32-14.3 32-32s-14.3-32-32-32l-288 0zM64 464a48 48 0 1 0 0-96 48 48 0 1 0 0 96zm48-208a48 48 0 1 0 -96 0 48 48 0 1 0 96 0z');}icon.appendChild(ic);}
          const name=document.createElement('span');
          name.className='yph-playlist-name svelte-181dlmc';
          name.textContent=playlist.title||'Bez tytułu';
          a.append(icon,name);
          a.addEventListener('click',()=>{
            setTimeout(updateActiveState,0);
          });
          box.appendChild(a);
        }
        sep.after(box);
      }
    }finally{
      if(observer)observer.observe(document.body,{childList:true,subtree:true});
    }
  }

  // Immediately restore the list from the last known data if the framework
  // re-rendered the sidebar and wiped our nodes.
  function restoreFromCache(){
    if(!cached||!document.body)return false;
    const groups=getGroups();
    if(!groups.length)return false;
    const missing=groups.filter(g=>!groupHasNav(g,cached.length>0));
    if(!missing.length)return false;
    buildNav(missing,cached);
    lastSignature=cached.map(p=>`${p.id}\u0000${p.title||""}`).join("\u0001");
    return true;
  }

  async function renderSavedPlaylistsNav(){
    if(!document.body||typeof window.getPlaylists!=="function") return;
    const groups=getGroups();
    if(!groups.length)return;
    let playlists=[];
    try{playlists=await window.getPlaylists()}catch{return}
    playlists=(Array.isArray(playlists)?playlists:[]).filter(p=>p&&p.id&&p.id!=="WL"&&p.id!=="LIKED"&&p.id!=="UPLOADS");
    let favId=null,mode="manual";try{const st=await window.getSettings();favId=st.watchLaterPlaylistId||null;mode=st.manageSortBy||"manual"}catch{}
    playlists=window.yphOrderPlaylists(playlists,{mode,order:await getOrder(),favId});
    const signature=playlists.map(p=>`${p.id}\u0000${p.title||""}`).join("\u0001");
    cached=playlists.map(p=>({id:p.id,title:p.title||""}));
    try{localStorage.setItem(CACHE_KEY,JSON.stringify({list:cached,ts:Date.now()}))}catch{}
    const current=getGroups();
    const needsRender=signature!==lastSignature||current.some(g=>!groupHasNav(g,playlists.length>0));
    if(!needsRender){updateActiveState();return}
    lastSignature=signature;
    buildNav(current,playlists);
  }

  function schedule(){clearTimeout(timer);timer=setTimeout(renderSavedPlaylistsNav,120)}

  installNavStyle();
  window.addEventListener('hashchange',()=>{restoreFromCache();updateActiveState();schedule()});
  window.addEventListener('popstate',()=>{restoreFromCache();updateActiveState();schedule()});
  window.addEventListener('update-saved-playlists',()=>{lastSignature="";schedule()});
  window.addEventListener('pageshow',()=>{restoreFromCache();updateActiveState();schedule()});
  observer=new MutationObserver(mutations=>{
    // Ignore changes made inside our own container; react to everything else,
    // including the removal of our nodes by a framework re-render.
    const relevant=mutations.some(m=>!m.target?.closest?.('[data-yph-saved-playlists]'));
    if(!relevant)return;
    if(restoreFromCache()){updateActiveState();schedule();return}
    schedule();
  });
  observer.observe(document.body,{childList:true,subtree:true});
  restoreFromCache();
  schedule();
})();
